cd /workspace/traces; mkdir -p /tmp/d; python3 -c "
import json,glob,os
for f in sorted(glob.glob('*/*.json')):
  d=json.load(open(f)); out=open('/tmp/d/'+d['trial_id']+'.txt','w')
  for i,m in enumerate(d['messages']):
    out.write(f'=== [{i}] {m.get(\"role\")}\n')
    if m.get('content'): out.write(str(m['content'])+'\n')
    for tc in m.get('tool_calls') or []:
      out.write('TOOLCALL '+tc['function']['name']+' '+tc['function']['arguments']+'\n')
    for k in m:
      if k not in ('content','tool_calls','role','agent_run_id'): out.write(f'  {k}: {str(m[k])[:300]}\n')
  out.write('=== OUTPUT\n'+str(d['output'])[:3000]+'\n')
"
wc -c /tmp/d/*; grep -il -E 'answer|ground.truth|solution|cheat|hidden|secret|expected' /tmp/d/*

